/// <summary>
/// The MobPickOrderTypeSales class handles the Sales Order data and posting logic.
/// </summary>
[TFMTableName(tableStr(SalesTable))]
class MobPickOrderTypeSales extends MobPickOrderType
{
    #Mob
    CustPackingSlipJour packingSlipJour;

}

Method.Source:
public Map getHeaderRecords(TFMRequestFiltersElement _filters, str _scannedValue)
{        
    InventLocation  inventLocation;
    Map             returnMap = new Map(Types::string, Types::Record);
    Common			ref = _filters.getReferredRecord();

    if ( ref.tableId == tableNum(MobPackingStation))
    {
        return returnMap;
    }

    inventLocation = MobHelper::getAllowedInventLocations(curUserId());
    while select inventLocation where (inventLocation.InventLocationId == _filters.parmWarehouse() || _filters.parmWarehouse() == MobConstants::all())
    {
        // Check if sales orders are enabled for this warehouse
        if (MobHelper::IsSalesOrderEnabled(inventLocation.InventLocationId))
        {
            // Use the warehouse from the current iteration
            returnMap = MobHelper::mergeMaps(returnMap,this.getSalesOrders(_filters,_scannedValue));
        }
    }    

    return returnMap;
}

public str getBackendID(Common _common)
{
    SalesTable salesTable = _common;
    return tableStr(SalesTable) + '/' + fieldStr(SalesTable,SalesId) + '/' + salesTable.SalesId + (salesTable.SalesType == SalesType::Sales ? '' : ('/' + MobConstants::ItemRequirement()));
}

