/// <summary>
///
/// </summary>
/// <param name = "_inventLocationID"></param>
/// <param name = "_deliveryDate"></param>
/// <param name = "_scannedValue"></param>
/// <returns></returns>
public Map getLineRecords(TFMRequestGetOrderLinesElement _request)
{
    Map         ret = new Map(Types::String,Types::Record);
    SalesLine   salesLine;
    InventDim   inventDim;
    WMSLocation wmsLocation;
    int         sorting = 1;
    SalesId     salesId = this.getSalesId(_request.parmBackendID()); // Remove the prefix

    if (!salesId || !SalesTable::exist(salesId))
    {
        throw error(strfmt(SalesTable::txtNotExist(),salesId));
    }
    while select salesLine
                where salesLine.SalesId == salesId &&
                      salesLine.SalesStatus == SalesStatus::Backorder &&
                      salesLine.SalesQty    > 0
                join inventDim
                where InventDim.inventDimId == salesLine.InventDimId
    {
        if (salesLine.isStocked() &&
                   MobInventLocationsGroupRights::existsUser(curUserId(), inventDim.InventLocationId) &&
                   MobHelper::IsSalesOrderEnabled(inventDim.InventLocationId) )
        {
            wmsLocation = WMSLocation::find(inventDim.wMSLocationId,inventDim.InventLocationId);
            ret.insert((wmsLocation.sortCode ? int2Str(wmsLocation.sortCode) : int2str(sorting)) + ';' + int642Str(SalesLine.RecId),salesLine);
            sorting++;

        }
    }

    return ret;
}

public Map getSalesOrders(TFMRequestFiltersElement _filters, SalesId _scannedValue)
{
    SalesTable				salesTable;
    SalesLine				salesLine;
    Map						returnMap = new Map(Types::string, Types::Record);
    QueryBuildDataSource    qbdsSalesTable;
    QueryBuildDataSource    qbdsSalesLine;
    Query                   q = new Query();
    QueryRun				qr;

    qbdsSalesTable = q.addDataSource(tableNum(SalesTable));
    qbdsSalesTable.addRange(fieldNum(SalesTable, SalesStatus)).value( queryValue(SalesStatus::Backorder));
    qbdsSalesTable.addRange(fieldNum(SalesTable, SalesType)).value( queryValue(SalesType::Sales));
    qbdsSalesTable.addRange(fieldNum(SalesTable, SalesType)).value( queryValue(SalesType::ItemReq));
    if (_scannedValue && SalesTable::exist(_scannedValue))
    {
        qbdsSalesTable.addRange(fieldNum(SalesTable,SalesId)).value(_scannedValue);
    }

    qbdsSalesLine = qbdsSalesTable.addDataSource(tableNum(SalesLine));
    qbdsSalesLine.addLink(fieldNum(SalesTable,SalesId), fieldNum(SalesLine,SalesId));
    qbdsSalesLine.addRange(fieldNum(SalesLine,SalesStatus)).value(queryValue(SalesStatus::Backorder));
    qbdsSalesLine.addRange(fieldNum(SalesLine, SalesQty)).value('>0');

    TFMFilterAdditionsDataBinding::modifyQuery(methodStr(MobDocPickOrder,PickOrderFilters) + strReplace(_filters.getFieldValue(extendedTypeStr(TFMOrderTypes)),';',''),q,_filters);

    qr = new QueryRun(q);
    while (qr.next())
    {            
        salesTable = qr.get(tableNum(SalesTable));
        salesLine = qr.get(tableNum(SalesLine));
        if ((salesLine.ShippingDateConfirmed && salesLine.ShippingDateConfirmed <= _filters.parmDeliveryDate() ) || (!salesLine.ShippingDateConfirmed && salesLine.ShippingDateRequested <= _filters.parmDeliveryDate() ))
        {
            if (salesLine.inventDim().InventLocationId == _filters.parmWarehouse() || _filters.parmWarehouse() == MobConstants::All())
            {
                if (MobInventLocationsGroupRights::existsUser(curUserId(), salesLine.inventDim().InventLocationId))
                {                
                    returnMap.insert(this.getBackendID(salesTable), salesTable);
                }
            }
        }
    }
    return returnMap;
}
